    public class DefaultAddressFactory : AddressFactory
    {
        private readonly Dictionary<string, AddressSpace> spaces = new(StringComparer.OrdinalIgnoreCase);
        private readonly AddressSpace defaultSpace;
        private readonly AddressSpace constSpace;

        public DefaultAddressFactory(AddressSpace defaultSpace, AddressSpace constSpace, params AddressSpace[] otherSpaces)
        {
            this.defaultSpace = defaultSpace;
            this.constSpace = constSpace;
            spaces[defaultSpace.getName()] = defaultSpace;
            spaces[constSpace.getName()] = constSpace;
            foreach (var s in otherSpaces)
                spaces[s.getName()] = s;
        }

        public AddressSpace getDefaultAddressSpace() => defaultSpace;
        public AddressSpace getConstantSpace() => constSpace;
        public AddressSpace? getAddressSpace(string name) => spaces.TryGetValue(name, out var s) ? s : null;
