    public class SleighLanguage : Language
    {
        private readonly AddressSpace ramSpace;
        private readonly AddressSpace regSpace;
        private readonly AddressSpace uniqSpace;
        private readonly AddressSpace constSpace;
        private readonly DefaultAddressFactory addrFactory;
        private readonly Dictionary<string, Register> registers = new(StringComparer.OrdinalIgnoreCase);
        private readonly Dictionary<string, int> useropIndices = new(StringComparer.OrdinalIgnoreCase);
        private readonly List<string> useropNames = new();
        private long uniqueBase;

        public SleighLanguage(bool is64Bit = true, long uniqueBase = 0)
        {
            this.uniqueBase = uniqueBase;
            ramSpace = new AddressSpace(SpaceNames.RAM_SPACE_NAME, 0, is64Bit ? 8 : 4);
            regSpace = new AddressSpace(SpaceNames.REGISTER_SPACE_NAME, 1, 4);
            uniqSpace = new AddressSpace(SpaceNames.UNIQUE_SPACE_NAME, 2, 8, isConst: false, isUniq: true);
            constSpace = new AddressSpace(SpaceNames.CONSTANT_SPACE_NAME, 3, 8, isConst: true);

            addrFactory = new DefaultAddressFactory(ramSpace, constSpace, regSpace, uniqSpace);

            if (is64Bit)
            {
                // mock 64-bit language registers
                AddRegister("r0", 0x0, 8);
                AddRegister("r1", 0x8, 8);
                AddRegister("r2", 0x10, 8);
                AddRegister("r3", 0x18, 8);
                AddRegister("r4", 0x20, 8);
                AddRegister("r5", 0x28, 8);
                AddRegister("r6", 0x30, 8);
                AddRegister("r7", 0x38, 8);
                AddRegister("sp", 0x40, 8);
                AddRegister("pc", 0x48, 8);

                AddUserOp("pcodeop_one");
                AddUserOp("pcodeop_two");
                AddUserOp("pcodeop_three");
            }
            else
            {
                // x86 language registers for PcodeParserTest
                AddRegister("AX", 0x0, 2);
                AddRegister("CX", 0x4, 2);
                AddRegister("ECX", 0x4, 4);
                AddRegister("BX", 0xc, 2);
            }
        }

        public void AddRegister(string name, long offset, int size)
        {
            var reg = new Register(name, regSpace.getAddress(offset), size);
            registers[name] = reg;
        }

        public void AddUserOp(string name)
        {
            if (!useropIndices.ContainsKey(name))
            {
                useropIndices[name] = useropNames.Count;
                useropNames.Add(name);
            }
        }

        public AddressFactory getAddressFactory() => addrFactory;
        public AddressSpace getDefaultSpace() => ramSpace;
        public AddressSpace getConstantSpace() => constSpace;
        public AddressSpace getUniqueSpace() => uniqSpace;
        public AddressSpace getRegisterSpace() => regSpace;

        public Register? getRegister(Address addr, int size)
        {
            foreach (var r in registers.Values)
            {
                if (r.getAddress().getOffset() == addr.getOffset() && r.getMinimumByteSize() == size)
                    return r;
            }
            return null;
        }

        public Register? getRegister(string name) => registers.TryGetValue(name, out var r) ? r : null;
        public bool isBigEndian() => true;
        public int getNumberOfUserDefinedOpNames() => useropNames.Count;
        public string getUserDefinedOpName(int index) => (index >= 0 && index < useropNames.Count) ? useropNames[index] : $"userop_{index}";
        public string? getUserOpName(int id) => getUserDefinedOpName(id);
        public long getUniqueBase() => uniqueBase;
        public void setUniqueBase(long b) => uniqueBase = b;
