namespace ghidra.pcode.exec
{
    [AttributeUsage(AttributeTargets.Method)]
    public class PcodeUseropAttribute : Attribute { }

    public class PcodeUseropSymbolMap
    {
        private readonly SleighLanguage language;
        private readonly Dictionary<int, string> idToName = new();
        private readonly Dictionary<string, int> nameToId = new(StringComparer.OrdinalIgnoreCase);

        public PcodeUseropSymbolMap(SleighLanguage language)
        {
            this.language = language;
            int count = language.getNumberOfUserDefinedOpNames();
            for (int i = 0; i < count; i++)
            {
                string name = language.getUserDefinedOpName(i);
                idToName[i] = name;
                nameToId[name] = i;
            }
        }

        public void AddUserop(string name, int id)
        {
            idToName[id] = name;
            nameToId[name] = id;
        }

        public string getUseropName(int id)
        {
            if (idToName.TryGetValue(id, out var name))
                return name;
            return language.getUserOpName(id) ?? $"userop_{id}";
        }

        public int getUseropIndex(string name)
        {
            if (nameToId.TryGetValue(name, out var id))
                return id;
            return -1;
        }

        public void addToParser(object parser) { }
    }

    public interface PcodeUseropLibrary<T>
    {
        PcodeUseropSymbolMap getSymbols(SleighLanguage language);
    }

    public class AnnotatedPcodeUseropLibrary<T> : PcodeUseropLibrary<T>
    {
        private readonly List<string> methodNames = new();

        public AnnotatedPcodeUseropLibrary()
        {
            var methods = GetType().GetMethods(System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic);
            foreach (var m in methods)
            {
                if (m.GetCustomAttributes(typeof(PcodeUseropAttribute), true).Length > 0)
                {
                    methodNames.Add(m.Name);
                }
            }
        }

        public PcodeUseropSymbolMap getSymbols(SleighLanguage language)
        {
            var map = new PcodeUseropSymbolMap(language);
            int nextId = language.getNumberOfUserDefinedOpNames();
            foreach (var name in methodNames)
            {
                map.AddUserop(name, nextId++);
            }
            return map;
        }
    }

    public class PcodeProgram
    {
        public SleighLanguage language { get; }
        public List<PcodeOp> code { get; }
        public PcodeUseropSymbolMap userops { get; }

        public PcodeProgram(SleighLanguage language, List<PcodeOp> code, PcodeUseropSymbolMap userops)
        {
            this.language = language;
            this.code = code;
            this.userops = userops;
        }

        public SleighLanguage getLanguage() => language;
        public List<PcodeOp> getCode() => code;
        public string getUseropName(int id) => userops.getUseropName(id);
        public int getUseropNumber(string name) => userops.getUseropIndex(name);

        public string formatVarnode(Varnode vn)
        {
            var space = vn.getSpace();
            if (space.isUniqueSpace())
            {
                return $"$U{vn.getOffset():x}:{vn.getSize()}";
            }
            if (space.isConstantSpace())
            {
                return $"{vn.getOffset()}:{vn.getSize()}";
            }
            if (space.getName() == SpaceNames.REGISTER_SPACE_NAME)
            {
                var reg = language.getRegister(vn.getAddress(), vn.getSize());
                if (reg != null)
                    return reg.getName();
            }
            return vn.ToString();
        }

        public string formatOp(PcodeOp op)
        {
            int opcode = op.getOpcode();
            if (opcode == PcodeOp.PTRADD)
            {
                // Label marker
                long labelId = op.getInput(0)?.getOffset() ?? 0;
                return $"<{labelId}>";
            }

            var sb = new StringBuilder();
            if (op.getOutput() != null)
            {
                sb.Append(formatVarnode(op.getOutput()!));
                sb.Append(" = ");
            }

            if (opcode == PcodeOp.LOAD)
            {
                sb.Append("LOAD ram(");
                var ptrVn = op.getInput(1)!;
                sb.Append(formatVarnode(ptrVn));
                sb.Append(")");
                return sb.ToString();
            }

            if (opcode == PcodeOp.CALLOTHER)
            {
                sb.Append("CALLOTHER ");
                long useropId = op.getInput(0)!.getOffset();
                string useropName = userops.getUseropName((int)useropId);
                sb.Append($"\"{useropName}\"");
                for (int i = 1; i < op.getNumInputs(); i++)
                {
                    sb.Append(", ");
                    sb.Append(formatVarnode(op.getInput(i)!));
                }
                return sb.ToString();
            }

            if (opcode == PcodeOp.CBRANCH)
            {
                sb.Append("CBRANCH ");
                long labelId = op.getInput(0)?.getOffset() ?? 0;
                sb.Append($"<{labelId}>, ");
                sb.Append(formatVarnode(op.getInput(1)!));
                return sb.ToString();
            }

            if (opcode == PcodeOp.BRANCH)
            {
                sb.Append("BRANCH ");
                sb.Append($"*[NO ADDRESS]0x{op.getInput(0)!.getOffset():x}");
                return sb.ToString();
            }

            sb.Append(PcodeOp.getMnemonic(opcode));
            for (int i = 0; i < op.getNumInputs(); i++)
            {
                sb.Append(i == 0 ? " " : ", ");
                sb.Append(formatVarnode(op.getInput(i)!));
            }
            return sb.ToString();
        }

        public virtual string toString()
        {
            var sb = new StringBuilder();
            sb.AppendLine("<PcodeProgram:");
            foreach (var op in code)
            {
                foreach (var lbl in op.LabelsBefore)
                {
                    sb.AppendLine($"<{lbl}>");
                }
                string line = formatOp(op);
                sb.AppendLine("  " + line);
                foreach (var lbl in op.LabelsAfter)
                {
                    sb.AppendLine($"<{lbl}>");
                }
            }
            sb.Append(">");
            return sb.ToString();
        }

        public override string ToString() => toString();
    }

    public class PcodeFrame
    {
        private readonly Language language;
        private readonly List<PcodeOp> code;
        private readonly PcodeUseropSymbolMap userops;
        private int _index = 0;
        private int branched = -1;
        private int count = 0;

        public PcodeFrame(Language language, List<PcodeOp> code, PcodeUseropSymbolMap userops)
        {
            this.language = language;
            this.code = code;
            this.userops = userops;
        }

        public int advance()
        {
            count++;
            return _index++;
        }

        public int stepBack()
        {
            count--;
            return _index--;
        }

        public void branch(int rel)
        {
            _index += rel - 1;
        }

        public void finishAsBranch()
        {
            branched = _index - 1;
            _index = -1;
        }

        public int index() => _index;
        public int getBranched() => branched;
        public bool isFallThrough() => _index == code.Count;
        public bool isBranch() => _index == -1;
        public bool isFinished() => !(0 <= _index && _index < code.Count);
        public List<PcodeOp> getCode() => code;
        public PcodeOp[] copyCode() => code.ToArray();
        public int resetCount()
        {
            int c = count;
            count = 0;
            return c;
        }
        public PcodeOp nextOp() => code[advance()];
        public string getUseropName(int id) => userops.getUseropName(id);

        public virtual string toString()
        {
            var sb = new StringBuilder();
            sb.Append($"<p-code frame: index={_index}");
            if (branched != -1)
            {
                sb.Append($" branched={branched}");
            }
            sb.AppendLine(" {");

            for (int i = 0; i < code.Count; i++)
            {
                var op = code[i];
                foreach (var lbl in op.LabelsBefore)
                {
                    sb.AppendLine($"  <{lbl}>");
                }

                string indicator = (i == branched) ? " *>" : (i == _index) ? " ->" : "   ";
                string addrStr = op.getSeqnum().getTarget().toString();
                long time = op.getSeqnum().getTime();
                string formattedOp = formatOp(op);
                sb.AppendLine($"{indicator} {addrStr}.{time}: {formattedOp}");

                foreach (var lbl in op.LabelsAfter)
                {
                    sb.AppendLine($"  <{lbl}>");
                }
            }

            if (isFallThrough())
            {
                sb.AppendLine(" *> fall-through");
            }

            sb.Append("}>");
            return sb.ToString();
        }

        private string formatVarnode(Varnode vn)
        {
            var space = vn.getSpace();
            if (space.isUniqueSpace())
            {
                return $"$U{vn.getOffset():x}:{vn.getSize()}";
            }
            if (space.isConstantSpace())
            {
                return $"{vn.getOffset()}:{vn.getSize()}";
            }
            if (space.getName() == SpaceNames.REGISTER_SPACE_NAME)
            {
                var reg = language.getRegister(vn.getAddress(), vn.getSize());
                if (reg != null)
                    return reg.getName();
            }
            return vn.ToString();
        }

        private string formatOp(PcodeOp op)
        {
            int opcode = op.getOpcode();
            var sb = new StringBuilder();
            if (op.getOutput() != null)
            {
                sb.Append(formatVarnode(op.getOutput()!));
                sb.Append(" = ");
            }

            if (opcode == PcodeOp.LOAD)
            {
                sb.Append("LOAD ram(");
                var ptrVn = op.getInput(1)!;
                sb.Append(formatVarnode(ptrVn));
                sb.Append(")");
                return sb.ToString();
            }

            if (opcode == PcodeOp.CALLOTHER)
            {
                sb.Append("CALLOTHER ");
                long useropId = op.getInput(0)!.getOffset();
                string useropName = userops.getUseropName((int)useropId);
                sb.Append($"\"{useropName}\"");
                for (int i = 1; i < op.getNumInputs(); i++)
                {
                    sb.Append(", ");
                    sb.Append(formatVarnode(op.getInput(i)!));
                }
                return sb.ToString();
            }

            if (opcode == PcodeOp.CBRANCH)
            {
                sb.Append("CBRANCH ");
                long labelId = op.getInput(0)?.getOffset() ?? 0;
                sb.Append($"<{labelId}>, ");
                sb.Append(formatVarnode(op.getInput(1)!));
                return sb.ToString();
            }

            if (opcode == PcodeOp.BRANCH)
            {
                sb.Append("BRANCH ");
                sb.Append($"*[NO ADDRESS]0x{op.getInput(0)!.getOffset():x}");
                return sb.ToString();
            }

            sb.Append(PcodeOp.getMnemonic(opcode));
            for (int i = 0; i < op.getNumInputs(); i++)
            {
                sb.Append(i == 0 ? " " : ", ");
                sb.Append(formatVarnode(op.getInput(i)!));
            }
            return sb.ToString();
        }

        public override string ToString() => toString();
    }

    public class SleighProgramCompiler
    {
        public static PcodeProgram compileProgram(SleighLanguage language, string sourceName, string source, PcodeUseropLibrary<object> library)
        {
            var symbols = library.getSymbols(language);
            var parser = new SleighStatementParser(language, symbols, 0x200);
            var ops = parser.CompileStatements(source);
            return new PcodeProgram(language, ops, symbols);
        }
    }

    public class SleighStatementParser
    {
        private readonly SleighLanguage language;
        private readonly PcodeUseropSymbolMap symbols;
        private long currentUniqueOffset;
        private readonly Dictionary<string, int> labels = new(StringComparer.OrdinalIgnoreCase);
        private readonly Dictionary<string, (int index, int size)> operands = new(StringComparer.OrdinalIgnoreCase);

        public SleighStatementParser(SleighLanguage language, PcodeUseropSymbolMap symbols, long uniqueBase)
        {
            this.language = language;
            this.symbols = symbols;
            this.currentUniqueOffset = uniqueBase;
        }

        public void AddOperand(string name, int index)
        {
            operands[name] = (index, 0);
        }

        public List<PcodeOp> CompileStatements(string text)
        {
            var ops = new List<PcodeOp>();
            var lines = text.Split(new[] { ';', (char)10, (char)13 })
                            .Select(l => l.Trim())
                            .Where(l => !string.IsNullOrEmpty(l));

            long seqOrder = 0;
            var pendingLabels = new List<long>();
            foreach (var rawLine in lines)
            {
                string line = rawLine.Trim();
                if (line.StartsWith("<") && line.EndsWith(">"))
                {
                    // Label definition
                    string labelName = line.Substring(1, line.Length - 2).Trim();
                    if (!labels.TryGetValue(labelName, out int labelId))
                    {
                        labelId = labels.Count;
                        labels[labelName] = labelId;
                    }
                    pendingLabels.Add(labelId);
                    currentUniqueOffset += 0x100;
                    continue;
                }

                // If condition goto
                if (line.StartsWith("if ") && line.Contains("goto "))
                {
                    int ifIdx = line.IndexOf('(');
                    int ifEnd = line.IndexOf(')');
                    string cond = line.Substring(ifIdx + 1, ifEnd - ifIdx - 1).Trim();
                    string dest = line.Substring(line.IndexOf("goto ") + 5).Trim();

                    // Evaluate condition
                    Varnode condVn = CompileCondition(cond, ops, ref seqOrder);

                    // Branch destination
                    long labelId = 0;
                    if (dest.StartsWith("<") && dest.EndsWith(">"))
                    {
                        string labName = dest.Substring(1, dest.Length - 2).Trim();
                        if (!labels.TryGetValue(labName, out int lId))
                        {
                            lId = labels.Count;
                            labels[labName] = lId;
                        }
                        labelId = lId;
                    }
                    var labelVn = new Varnode(language.getConstantSpace().getAddress(labelId), 4);
                    AddOp(ops, new PcodeOp(new SequenceNumber(Address.NO_ADDRESS, seqOrder++), PcodeOp.CBRANCH, new[] { labelVn, condVn }, null), pendingLabels);
                    continue;
                }

                // Unconditional goto
                if (line.StartsWith("goto "))
                {
                    string dest = line.Substring(5).Trim();
                    long targetAddr = 0;
                    if (dest.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
                        targetAddr = Convert.ToInt64(dest.Substring(2), 16);
                    else
                        targetAddr = Convert.ToInt64(dest);

                    var targetVn = new Varnode(language.getDefaultSpace().getAddress(targetAddr), 8);
                    AddOp(ops, new PcodeOp(new SequenceNumber(Address.NO_ADDRESS, seqOrder++), PcodeOp.BRANCH, new[] { targetVn }, null), pendingLabels);
                    continue;
                }

                // Userop or funcall: e.g. pcodeop_one(r0) or __lib_userop(r0)
                var callMatch = Regex.Match(line, @"^([a-zA-Z0-9_]+)\s*\((.*?)\)$");
                if (callMatch.Success && !line.Contains("="))
                {
                    string funcName = callMatch.Groups[1].Value;
                    string argsStr = callMatch.Groups[2].Value.Trim();
                    int useropId = symbols.getUseropIndex(funcName);
                    if (useropId < 0)
                        useropId = language.getNumberOfUserDefinedOpNames();

                    var inputs = new List<Varnode>();
                    inputs.Add(new Varnode(language.getConstantSpace().getAddress(useropId), 4));
                    if (!string.IsNullOrEmpty(argsStr))
                    {
                        var argParts = argsStr.Split(',').Select(a => a.Trim());
                        foreach (var arg in argParts)
                        {
                            inputs.Add(ParseVarnode(arg));
                        }
                    }
                    AddOp(ops, new PcodeOp(new SequenceNumber(Address.NO_ADDRESS, seqOrder++), PcodeOp.CALLOTHER, inputs.ToArray(), null), pendingLabels);
                    continue;
                }

                // Assignment: lvalue = expr
                int eqIdx = line.IndexOf('=');
                if (eqIdx > 0)
                {
                    string lhs = line.Substring(0, eqIdx).Trim();
                    string rhs = line.Substring(eqIdx + 1).Trim();

                    // Load: r0 = *:8 r1
                    if (rhs.StartsWith("*"))
                    {
                        // *:8 r1 or *[ram]:8 r1
                        var loadMatch = Regex.Match(rhs, @"^\*(\[(\w+)\])?\s*:\s*(\d+)\s+(.+)$");
                        if (loadMatch.Success)
                        {
                            string spaceName = loadMatch.Groups[2].Success ? loadMatch.Groups[2].Value : "ram";
                            int size = int.Parse(loadMatch.Groups[3].Value);
                            string ptrStr = loadMatch.Groups[4].Value.Trim();
                            var ptrVn = ParseVarnode(ptrStr);
                            var spaceVn = new Varnode(language.getConstantSpace().getAddress(0), 8);
                            var outVn = ParseVarnode(lhs, size);
                            AddOp(ops, new PcodeOp(new SequenceNumber(Address.NO_ADDRESS, seqOrder++), PcodeOp.LOAD, new[] { spaceVn, ptrVn }, outVn), pendingLabels);
                            continue;
                        }
                    }

                    // Arithmetic / Expressions: r0 + r1 + r2 or r0 + r1 or r2 + 1
                    CompileAssignment(lhs, rhs, ops, ref seqOrder, pendingLabels);
                    continue;
                }
            }

            if (pendingLabels.Count > 0 && ops.Count > 0)
            {
                ops[^1].LabelsAfter.AddRange(pendingLabels);
                pendingLabels.Clear();
            }
            return ops;
        }

        private void AddOp(List<PcodeOp> ops, PcodeOp op, List<long> pendingLabels)
        {
            if (pendingLabels.Count > 0)
            {
                op.LabelsBefore.AddRange(pendingLabels);
                pendingLabels.Clear();
            }
            ops.Add(op);
        }

        private Varnode CompileCondition(string cond, List<PcodeOp> ops, ref long seqOrder)
        {
            string opStr;
            int opcode;
            if (cond.Contains("=="))
            {
                opStr = "==";
                opcode = PcodeOp.INT_EQUAL;
            }
            else if (cond.Contains("!="))
            {
                opStr = "!=";
                opcode = PcodeOp.INT_NOTEQUAL;
            }
            else
            {
                throw new NotImplementedException("Unsupported condition operator: " + cond);
            }

            string[] parts = cond.Split(new[] { opStr }, StringSplitOptions.None);
            var leftVn = ParseVarnode(parts[0].Trim());
            var rightVn = ParseVarnode(parts[1].Trim(), leftVn.getSize());

            var tempVn = new Varnode(language.getUniqueSpace().getAddress(currentUniqueOffset), 1);
            currentUniqueOffset += 0x100;

            ops.Add(new PcodeOp(new SequenceNumber(Address.NO_ADDRESS, seqOrder++), opcode, new[] { leftVn, rightVn }, tempVn));
            return tempVn;
        }

        private void CompileAssignment(string lhs, string rhs, List<PcodeOp> ops, ref long seqOrder, List<long> pendingLabels)
        {
            var outVn = ParseVarnode(lhs);

            // Check for binary operations (+, <<, etc.)
            // Handle chained binary ops: a + b + c
            if (rhs.Contains("+"))
            {
                var terms = rhs.Split('+').Select(t => t.Trim()).ToList();
                if (terms.Count == 2)
                {
                    var left = ParseVarnode(terms[0]);
                    var right = ParseVarnode(terms[1], left.getSize());
                    AddOp(ops, new PcodeOp(new SequenceNumber(Address.NO_ADDRESS, seqOrder++), PcodeOp.INT_ADD, new[] { left, right }, outVn), pendingLabels);
                }
                else if (terms.Count > 2)
                {
                    // First term: $U200:8 = INT_ADD terms[0], terms[1]
                    var tempVn = new Varnode(language.getUniqueSpace().getAddress(currentUniqueOffset), outVn.getSize());
                    currentUniqueOffset += 0x100;
                    var t0 = ParseVarnode(terms[0]);
                    var t1 = ParseVarnode(terms[1]);
                    ops.Add(new PcodeOp(new SequenceNumber(Address.NO_ADDRESS, seqOrder++), PcodeOp.INT_ADD, new[] { t0, t1 }, tempVn));

                    // Subsequent terms
                    Varnode curr = tempVn;
                    for (int i = 2; i < terms.Count - 1; i++)
                    {
                        var nextTemp = new Varnode(language.getUniqueSpace().getAddress(currentUniqueOffset), outVn.getSize());
                        currentUniqueOffset += 0x100;
                        ops.Add(new PcodeOp(new SequenceNumber(Address.NO_ADDRESS, seqOrder++), PcodeOp.INT_ADD, new[] { curr, ParseVarnode(terms[i]) }, nextTemp));
                        curr = nextTemp;
                    }
                    AddOp(ops, new PcodeOp(new SequenceNumber(Address.NO_ADDRESS, seqOrder++), PcodeOp.INT_ADD, new[] { curr, ParseVarnode(terms[^1]) }, outVn), pendingLabels);
                }
                return;
            }

            if (rhs.Contains("<<"))
            {
                var parts = rhs.Split(new[] { "<<" }, StringSplitOptions.None).Select(p => p.Trim()).ToArray();
                var left = ParseVarnode(parts[0]);
                var right = ParseVarnode(parts[1], 4);
                AddOp(ops, new PcodeOp(new SequenceNumber(Address.NO_ADDRESS, seqOrder++), PcodeOp.INT_LEFT, new[] { left, right }, outVn), pendingLabels);
                return;
            }

            // Copy
            var inVn = ParseVarnode(rhs, outVn.getSize());
            AddOp(ops, new PcodeOp(new SequenceNumber(Address.NO_ADDRESS, seqOrder++), PcodeOp.COPY, new[] { inVn }, outVn), pendingLabels);
        }

        public Varnode ParseVarnode(string token, int defaultSize = 8)
        {
            token = token.Trim();
            if (token.Contains(":"))
            {
                var parts = token.Split(':');
                string name = parts[0].Trim();
                int size = int.Parse(parts[1].Trim());
                return ParseVarnodeWithName(name, size);
            }
            return ParseVarnodeWithName(token, defaultSize);
        }

        private Varnode ParseVarnodeWithName(string name, int size)
        {
            if (name.StartsWith("$U", StringComparison.OrdinalIgnoreCase))
            {
                long offset = Convert.ToInt64(name.Substring(2), 16);
                return new Varnode(language.getUniqueSpace().getAddress(offset), size);
            }

            var reg = language.getRegister(name);
            if (reg != null)
            {
                return new Varnode(reg.getAddress(), size != 0 ? size : reg.getMinimumByteSize());
            }

            if (long.TryParse(name, out long val))
            {
                return new Varnode(language.getConstantSpace().getAddress(val), size);
            }

            if (name.StartsWith("0x", StringComparison.OrdinalIgnoreCase) && long.TryParse(name.Substring(2), System.Globalization.NumberStyles.HexNumber, null, out long hexVal))
            {
                return new Varnode(language.getConstantSpace().getAddress(hexVal), size);
            }

            // Named temporary in unique space
            var tempVn = new Varnode(language.getUniqueSpace().getAddress(currentUniqueOffset), size != 0 ? size : 8);
            currentUniqueOffset += 0x100;
            return tempVn;
        }
    }

}

namespace ghidra.program.model.lang
{
    public class PcodeParser
    {
        private readonly SleighLanguage language;
        private readonly long uniqueBase;
        private readonly Dictionary<string, int> operands = new(StringComparer.OrdinalIgnoreCase);

        public PcodeParser(SleighLanguage language, long uniqueBase)
        {
            this.language = language;
            this.uniqueBase = uniqueBase;
        }

        public void addOperand(Location loc, string name, int index)
        {
            operands[name] = index;
        }

        public ConstructTpl compilePcode(string pcodeStatements, string srcFile, int srcLine)
        {
            var opTpls = new List<OpTpl>();
            long currentUnique = uniqueBase;
            int labelIndex = 0;
            var labelMap = new Dictionary<string, int>();

            var lines = pcodeStatements.Split(new[] { ';', (char)10, (char)13 })
                                      .Select(l => l.Trim())
                                      .Where(l => !string.IsNullOrEmpty(l));

            var constSpace = language.getConstantSpace();
            var uniqueSpace = language.getUniqueSpace();
            var regSpace = language.getRegisterSpace();

            foreach (var rawLine in lines)
            {
                string line = rawLine.Trim();

                // Label: <lab>
                if (line.StartsWith("<") && line.EndsWith(">"))
                {
                    string labName = line.Substring(1, line.Length - 2).Trim();
                    int lId = labelIndex++;
                    labelMap[labName] = lId;
                    var idvn = new VarnodeTpl(new ConstTpl(constSpace), new ConstTpl(ConstTpl.REAL, lId), new ConstTpl(ConstTpl.REAL, 4));
                    var labelOp = new OpTpl(PcodeOp.PTRADD, null, idvn);
                    opTpls.Add(labelOp);
                    continue;
                }

                // If condition goto
                if (line.StartsWith("if ") && line.Contains("goto "))
                {
                    int ifIdx = line.IndexOf('(');
                    int ifEnd = line.IndexOf(')');
                    string cond = line.Substring(ifIdx + 1, ifEnd - ifIdx - 1).Trim();
                    string dest = line.Substring(line.IndexOf("goto ") + 5).Trim();

                    // Parse condition
                    string opStr = cond.Contains("==") ? "==" : "!=";
                    int opCode = cond.Contains("==") ? PcodeOp.INT_EQUAL : PcodeOp.INT_NOTEQUAL;
                    var parts = cond.Split(new[] { opStr }, StringSplitOptions.None).Select(p => p.Trim()).ToArray();
                    var lhs = ParseVarnodeTpl(parts[0], 2);
                    var rhs = ParseVarnodeTpl(parts[1], 2);

                    var tempOut = new VarnodeTpl(new ConstTpl(uniqueSpace), new ConstTpl(ConstTpl.REAL, currentUnique), new ConstTpl(ConstTpl.REAL, 1));
                    currentUnique += 0x100;

                    opTpls.Add(new OpTpl(opCode, tempOut, lhs, rhs));

                    // CBRANCH
                    VarnodeTpl destTpl;
                    if (dest == "inst_next")
                    {
                        destTpl = new VarnodeTpl(new ConstTpl(ConstTpl.J_CURSPACE, 0), new ConstTpl(ConstTpl.J_NEXT, 0), new ConstTpl(ConstTpl.J_CURSPACE_SIZE, 0));
                    }
                    else if (dest == "inst_next2")
                    {
                        destTpl = new VarnodeTpl(new ConstTpl(ConstTpl.J_CURSPACE, 0), new ConstTpl(ConstTpl.J_NEXT2, 0), new ConstTpl(ConstTpl.J_CURSPACE_SIZE, 0));
                    }
                    else if (dest.StartsWith("<") && dest.EndsWith(">"))
                    {
                        string labName = dest.Substring(1, dest.Length - 2).Trim();
                        destTpl = new VarnodeTpl(new ConstTpl(constSpace), new ConstTpl(ConstTpl.J_RELATIVE, 0), new ConstTpl(ConstTpl.REAL, 4));
                    }
                    else
                    {
                        destTpl = ParseVarnodeTpl(dest, 4);
                    }

                    opTpls.Add(new OpTpl(PcodeOp.CBRANCH, null, destTpl, tempOut));
                    continue;
                }

                // Call: call [ECX]
                if (line.StartsWith("call [") && line.EndsWith("]"))
                {
                    string inner = line.Substring(6, line.Length - 7).Trim();
                    var ptrVn = ParseVarnodeTpl(inner, 4);
                    opTpls.Add(new OpTpl(PcodeOp.CALLIND, null, ptrVn));
                    continue;
                }

                // Assignment: lhs = rhs
                int eqIdx = line.IndexOf('=');
                if (eqIdx > 0)
                {
                    string lhs = line.Substring(0, eqIdx).Trim();
                    string rhs = line.Substring(eqIdx + 1).Trim();

                    // Parse LHS
                    VarnodeTpl outTpl;
                    int outSize = 2;
                    if (lhs.Contains(":"))
                    {
                        var parts = lhs.Split(':');
                        string name = parts[0].Trim();
                        outSize = int.Parse(parts[1].Trim());
                        outTpl = new VarnodeTpl(new ConstTpl(uniqueSpace), new ConstTpl(ConstTpl.REAL, currentUnique), new ConstTpl(ConstTpl.REAL, outSize));
                        currentUnique += 0x100;
                    }
                    else if (operands.TryGetValue(lhs, out int opIdx))
                    {
                        outTpl = new VarnodeTpl(new ConstTpl(ConstTpl.HANDLE, opIdx, ConstTpl.V_SPACE),
                                                new ConstTpl(ConstTpl.HANDLE, opIdx, ConstTpl.V_OFFSET),
                                                new ConstTpl(ConstTpl.HANDLE, opIdx, ConstTpl.V_SIZE));
                    }
                    else
                    {
                        outTpl = ParseVarnodeTpl(lhs, 2);
                    }

                    // RHS
                    if (rhs == "inst_next")
                    {
                        var inTpl = new VarnodeTpl(new ConstTpl(constSpace), new ConstTpl(ConstTpl.J_NEXT, 0), new ConstTpl(ConstTpl.REAL, outSize));
                        opTpls.Add(new OpTpl(PcodeOp.COPY, outTpl, inTpl));
                        continue;
                    }
                    if (rhs == "inst_next2")
                    {
                        var inTpl = new VarnodeTpl(new ConstTpl(constSpace), new ConstTpl(ConstTpl.J_NEXT2, 0), new ConstTpl(ConstTpl.REAL, outSize));
                        opTpls.Add(new OpTpl(PcodeOp.COPY, outTpl, inTpl));
                        continue;
                    }
                    if (rhs.Contains("<<"))
                    {
                        var parts = rhs.Split(new[] { "<<" }, StringSplitOptions.None).Select(p => p.Trim()).ToArray();
                        var left = ParseVarnodeTpl(parts[0], 2);
                        var right = ParseVarnodeTpl(parts[1], 4);
                        opTpls.Add(new OpTpl(PcodeOp.INT_LEFT, outTpl, left, right));
                        continue;
                    }
                    if (rhs.Contains("+"))
                    {
                        var parts = rhs.Split('+').Select(p => p.Trim()).ToArray();
                        var left = ParseVarnodeTpl(parts[0], 0);
                        VarnodeTpl right;
                        int sizeHandle = operands.TryGetValue(lhs, out int oIdx) ? oIdx : (operands.TryGetValue(parts[0], out int pIdx) ? pIdx : 0);
                        if (long.TryParse(parts[1], out long cVal))
                        {
                            right = new VarnodeTpl(new ConstTpl(constSpace),
                                                   new ConstTpl(ConstTpl.REAL, cVal),
                                                   new ConstTpl(ConstTpl.HANDLE, sizeHandle, ConstTpl.V_SIZE));
                        }
                        else
                        {
                            right = ParseVarnodeTpl(parts[1], 0);
                        }
                        opTpls.Add(new OpTpl(PcodeOp.INT_ADD, outTpl, left, right));
                        continue;
                    }

                    // Simple copy
                    var simpleIn = ParseVarnodeTpl(rhs, outSize);
                    opTpls.Add(new OpTpl(PcodeOp.COPY, outTpl, simpleIn));
                }
            }

            return new ConstructTpl(opTpls, labelIndex);
        }

        private VarnodeTpl ParseVarnodeTpl(string name, int defaultSize)
        {
            name = name.Trim();
            if (operands.TryGetValue(name, out int opIdx))
            {
                return new VarnodeTpl(new ConstTpl(ConstTpl.HANDLE, opIdx, ConstTpl.V_SPACE),
                                      new ConstTpl(ConstTpl.HANDLE, opIdx, ConstTpl.V_OFFSET),
                                      new ConstTpl(ConstTpl.HANDLE, opIdx, ConstTpl.V_SIZE));
            }

            var reg = language.getRegister(name);
            if (reg != null)
            {
                return new VarnodeTpl(new ConstTpl(language.getRegisterSpace()),
                                      new ConstTpl(ConstTpl.REAL, reg.getAddress().getOffset()),
                                      new ConstTpl(ConstTpl.REAL, reg.getMinimumByteSize()));
            }

            if (long.TryParse(name, out long val))
            {
                return new VarnodeTpl(new ConstTpl(language.getConstantSpace()),
                                      new ConstTpl(ConstTpl.REAL, val),
                                      new ConstTpl(ConstTpl.REAL, defaultSize));
            }

            return new VarnodeTpl(new ConstTpl(language.getDefaultSpace()),
                                  new ConstTpl(ConstTpl.REAL, 0),
                                  new ConstTpl(ConstTpl.REAL, defaultSize));
        }
    }
}
